mapper.select:
select a.id,a.merchant_id,a.type,a.name,a.identity_card,a.subject_type,a.subject_name,a.license_no,a.status as audit_status, a.reason,a.review_time,a.submit_time from authentication a left join merchant m on a.merchant_id = m.id left join seller_authentication sa on sa.merchant_id = m.id
and a.type = #{param.type.name}
and m.name like concat("%",#{param.keyword},"%")
and m.seller = 1
and m.buyer = 1
and a.status = #{param.auditStatus.name}
and sa.status = #{param.sellerStatus.name}
and a.status in ("AUTH_UNAUTHORIZED","AUTH_PASSED","AUTH_FAILED","AUTH_AUDIT")
group by id order by a.submit_time desc,a.status asc,sa.status asc
